/**
 * Synthetic question bank used ONLY by tests. Its content is mechanical
 * (generated by simple modular patterns) and has no psychological meaning.
 * It must never be shipped or used as an editorial bank.
 */
import type {
  AssessmentModule,
  FunctioningBand,
  Question,
  QuestionOption,
} from "@/domain/assessment/types";
import {
  ENNEAGRAM_TYPES,
  INSTINCTS,
  wingsOf,
  type EnneagramType,
} from "@/domain/enneagram/structure";

const asType = (n: number): EnneagramType => ((((n % 9) + 9) % 9) + 1) as EnneagramType;

/** Builds a question with sane defaults; override anything. */
export function makeQuestion(
  partial: Partial<Question> & Pick<Question, "id" | "module" | "options">,
): Question {
  return {
    code: partial.id.toUpperCase().replace(/-/g, "_"),
    version: 1,
    text: `Pregunta sintética ${partial.id}`,
    kind: "scenario-choice",
    relatedTypes: [],
    dimensions: ["synthetic"],
    weight: 1,
    discrimination: 0.7,
    rationale: "synthetic test fixture",
    references: [],
    reviewStatus: "draft",
    active: true,
    ...partial,
  };
}

function buildTypeQuestions(): Question[] {
  // Equivalence pairs (indices): never both asked, compared if both answered.
  const groupOf: Record<number, string> = {
    3: "eq-a", 12: "eq-a",
    6: "eq-b", 15: "eq-b",
    9: "eq-c", 18: "eq-c",
    21: "eq-d", 24: "eq-d",
  };
  const steps = [1, 2, 4]; // gcd(step, 9) = 1 => 4 distinct types per question
  const out: Question[] = [];
  for (let i = 0; i < 27; i++) {
    const step = steps[Math.floor(i / 9)];
    const options: QuestionOption[] = [0, 1, 2, 3].map((j) => {
      const primary = asType(i + j * step);
      const secondary = asType(primary - 1 + 4); // constant offset: weak signal
      return {
        id: `q-type-${String(i + 1).padStart(3, "0")}-o${j}`,
        text: `Opción ${j}`,
        scores: { types: { [primary]: 3, [secondary]: 1 } },
      };
    });
    const touched = [...new Set(options.flatMap((o) => Object.keys(o.scores.types ?? {}).map(Number)))];
    out.push(
      makeQuestion({
        id: `q-type-${String(i + 1).padStart(3, "0")}`,
        module: "type",
        options,
        relatedTypes: touched as EnneagramType[],
        discrimination: 0.5 + 0.1 * (i % 5),
        equivalenceGroup: groupOf[i],
      }),
    );
  }
  return out;
}

function buildWingQuestions(): Question[] {
  const out: Question[] = [];
  for (const main of ENNEAGRAM_TYPES) {
    const [lo, hi] = wingsOf(main);
    for (const v of [1, 2]) {
      const id = `q-wing-${main}-${v}`;
      out.push(
        makeQuestion({
          id,
          module: "wing",
          kind: "forced-choice",
          relatedTypes: [main],
          options: [
            { id: `${id}-lo`, text: "Hacia el vecino inferior", scores: { types: { [lo]: 3 } } },
            { id: `${id}-hi`, text: "Hacia el vecino superior", scores: { types: { [hi]: 3 } } },
            { id: `${id}-mix`, text: "Ambos", scores: { types: { [lo]: 1, [hi]: 1 } } },
          ],
        }),
      );
    }
  }
  return out;
}

function buildInstinctQuestions(): Question[] {
  const out: Question[] = [];
  for (let i = 0; i < 10; i++) {
    const id = `q-inst-${String(i + 1).padStart(3, "0")}`;
    out.push(
      makeQuestion({
        id,
        module: "instinct",
        kind: "forced-choice",
        options: INSTINCTS.map((ins, j) => ({
          id: `${id}-${ins}`,
          text: `Opción ${j}`,
          scores: { instincts: { [ins]: 3 } },
        })),
      }),
    );
  }
  return out;
}

const BANDS: FunctioningBand[] = ["flexible", "intermediate", "maladaptive"];

function buildFunctioningQuestions(): Question[] {
  const out: Question[] = [];
  for (let i = 0; i < 12; i++) {
    const id = `q-func-${String(i + 1).padStart(3, "0")}`;
    out.push(
      makeQuestion({
        id,
        module: "functioning",
        kind: "frequency",
        timeWindow: "last-4-weeks",
        options: BANDS.map((b) => ({
          id: `${id}-${b}`,
          text: b,
          scores: { bands: { [b]: 3 } },
        })),
      }),
    );
  }
  return out;
}

export function buildMiniBank(): Question[] {
  return [
    ...buildTypeQuestions(),
    ...buildWingQuestions(),
    ...buildInstinctQuestions(),
    ...buildFunctioningQuestions(),
  ];
}

export const MINI_BANK: readonly Question[] = buildMiniBank();

export function byModule(bank: readonly Question[], module: AssessmentModule): Question[] {
  return bank.filter((q) => q.module === module);
}

/** Option of `q` with the highest score for `type` (undefined if none scores it). */
export function optionGiving(q: Question, type: EnneagramType): QuestionOption | undefined {
  let best: QuestionOption | undefined;
  let bestScore = 0;
  for (const o of q.options) {
    const s = o.scores.types?.[type] ?? 0;
    if (s > bestScore) {
      best = o;
      bestScore = s;
    }
  }
  return best;
}

/** Deterministic PRNG (mulberry32) for reproducible synthetic respondents. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Synthetic respondent biased toward `type`: picks the option that most favours
 * it when available, otherwise a seeded-random option; with probability `noise`
 * answers at random. Instinct/functioning/wing are biased as requested.
 */
export function syntheticRespondent(opts: {
  type: EnneagramType;
  wingTowardUpper?: boolean;
  instinct?: (typeof INSTINCTS)[number];
  band?: FunctioningBand;
  noise?: number;
  seed?: number;
}): (q: Question) => string {
  const rnd = mulberry32(opts.seed ?? 1);
  const noise = opts.noise ?? 0.1;
  const random = (q: Question) => q.options[Math.floor(rnd() * q.options.length)].id;
  return (q) => {
    if (rnd() < noise) return random(q);
    switch (q.module) {
      case "type":
        return (optionGiving(q, opts.type) ?? q.options[Math.floor(rnd() * q.options.length)]).id;
      case "wing": {
        const [lo, hi] = wingsOf(opts.type);
        const target = opts.wingTowardUpper ? hi : lo;
        return (optionGiving(q, target) ?? q.options[0]).id;
      }
      case "instinct": {
        const want = opts.instinct ?? "sp";
        return (q.options.find((o) => (o.scores.instincts?.[want] ?? 0) > 0) ?? q.options[0]).id;
      }
      case "functioning": {
        const want = opts.band ?? "flexible";
        return (q.options.find((o) => (o.scores.bands?.[want] ?? 0) > 0) ?? q.options[0]).id;
      }
    }
  };
}
